            FfiConverterOptionString.write(panicBacktrace, into: &buf)


        case let .error(error):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(error, into: &buf)


        case .earlyTermination:
            writeInt(&buf, Int32(3))

        }
    }
}


